// @ts-nocheck -- route search types are generated by the embedded app.
//
// The activity ledger: one activity's definition (video/audio iframe, reading
// body, the focused learner's graded quiz attempt) with the list of learners
// who completed the same activity at the source underneath. Report details
// (months, hours, editing) live on each learner's own journal.
import { useQuery } from "@tanstack/react-query";
import { createFileRoute, Link, useRouter } from "@tanstack/react-router";
import { decodeEntities } from "@/features/audit/learner-log-pro-copy/components/ManualActivityRow";
import { QuizBody } from "@/features/audit/learner-log-pro-copy/components/QuizAttemptBody";
import {
  getActivityLedger,
  type LedgerSourceParticipant,
} from "@/features/audit/learner-log-pro-copy/lib/manualApi";
import { toGoogleEmbedUrl } from "@/features/audit/learner-log-pro-copy/lib/googleEmbed";

export const Route = createFileRoute("/ledger")({
  // learner=6441 in a hand-typed URL arrives as a number — accept both forms.
  validateSearch: (search: Record<string, unknown>) => ({
    ref: typeof search.ref === "string" ? search.ref : typeof search.ref === "number" ? String(search.ref) : "",
    learner: typeof search.learner === "string" ? search.learner : typeof search.learner === "number" ? String(search.learner) : "",
  }),
  component: LedgerPage,
});

function categoryBadgeClass(category: string) {
  switch ((category || "").toLowerCase()) {
    case "video": return "bg-primary/15 text-primary";
    case "audio": return "bg-[#673ab7]/15 text-[#673ab7]";
    case "reading+quiz": return "bg-success/15 text-success";
    case "attendance": return "bg-amber-500/15 text-amber-700";
    case "assignment": return "bg-[#182d48]/10 text-[#182d48]";
    default: return "bg-muted text-muted-foreground";
  }
}

// The learner's graded attempt (QuizBody) replaced the old generic quiz
// definition block — the ledger shows how the FOCUSED learner solved it.
function QuizResultBlock({ aptemId, learnerName, component }: { aptemId: number | null; learnerName: string; component: string | number }) {
  if (!aptemId) {
    return <p className="px-7 pb-4 text-sm text-muted-foreground">Open this ledger from a learner's journal row to see their graded attempt.</p>;
  }
  return <div className="px-2 pb-3"><QuizBody aptemId={aptemId} learnerName={learnerName} component={String(component)} /></div>;
}

// Everyone who completed (or attended) the same activity at the source —
// names only. Hours, months and editing live on each learner's own journal.
function doneLearners(sourceParticipants: LedgerSourceParticipant[]) {
  return sourceParticipants
    .filter((item) => item.status === "completed" || item.status === "attended")
    .sort((left, right) => left.learner_name.localeCompare(right.learner_name));
}

function LedgerPage() {
  const router = useRouter();
  const { ref, learner } = Route.useSearch();

  const ledger = useQuery({
    queryKey: ["activity-ledger", ref],
    queryFn: () => getActivityLedger(ref),
    enabled: Boolean(ref),
  });

  const activity = ledger.data?.activity;
  const participants = ledger.data?.participants ?? [];
  const sourceParticipants = ledger.data?.source_participants ?? [];
  const isMedia = ["video", "audio"].includes((ledger.data?.category ?? "").toLowerCase());
  const isAttendanceLedger = (ledger.data?.category ?? "").toLowerCase() === "attendance";
  const completedList = doneLearners(sourceParticipants);
  // The learner this ledger was opened FOR (journal row link) — their graded
  // quiz attempt renders in place of the old generic quiz definition.
  const focusedAptemId = Number(String(learner).replace(/^"|"$/g, "")) || null;
  const focusedName =
    participants.find((item) => item.aptem_id === focusedAptemId)?.learner_name ??
    sourceParticipants.find((item) => item.aptem_id === focusedAptemId)?.learner_name ?? "";

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="flex w-full flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Activity ledger</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <button type="button" onClick={() => router.history.back()} className="font-medium text-foreground hover:underline">← Back</button>
            <Link to="/journal" search={{ learner } as never} className="font-medium hover:underline">Journal</Link>
            <Link to="/search" className="font-medium hover:underline">Search</Link>
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-[1500px] space-y-6 px-6 py-8">
        {!ref ? (
          <p className="py-10 text-center text-sm text-muted-foreground">No activity reference was provided.</p>
        ) : ledger.isLoading ? (
          <p className="py-10 text-center text-sm text-muted-foreground">Loading activity ledger…</p>
        ) : ledger.isError ? (
          <p className="py-10 text-center text-sm text-destructive">{ledger.error instanceof Error ? ledger.error.message : "Could not load the activity ledger."}</p>
        ) : activity ? (
          <>
            <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
              <div className="h-1 bg-[#182d48]" />
              <div className="flex flex-wrap items-start justify-between gap-4 px-7 py-6">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className={`rounded-sm px-2 py-0.5 text-[10px] font-semibold uppercase ${categoryBadgeClass(ledger.data.category)}`}>{ledger.data.category}</span>
                    {activity.activity_date ? <span className="font-mono text-xs text-muted-foreground">{activity.activity_date}</span> : null}
                    {activity.module ? <span className="text-xs text-muted-foreground">{activity.module}</span> : null}
                  </div>
                  <h1 className="mt-2 text-2xl font-semibold tracking-tight text-[#182d48]">{decodeEntities(activity.title)}</h1>
                </div>
                {activity.configured_duration_minutes ? (
                  <div className="rounded-xl bg-[#f6f8fb] px-6 py-3 text-center">
                    <p className="text-[9px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">Configured duration</p>
                    <p className="mt-1 font-mono text-sm font-semibold text-[#182d48]">{activity.configured_duration_minutes} min</p>
                  </div>
                ) : null}
              </div>

              {activity.parts && activity.parts.length > 1 ? (
                // A merged Reading+Quiz bundle: every part gets its own
                // content/reading/quiz block under its own title.
                activity.parts.map((part) => (
                  <div key={part.activity_id} className="border-t border-border">
                    <div className="flex items-center justify-between px-7 py-3">
                      <p className="label-caps">{decodeEntities(part.title)}</p>
                      {part.content_url ? (
                        <a href={part.content_url} target="_blank" rel="noreferrer" className="text-xs font-medium text-primary hover:underline">Open in new tab ↗</a>
                      ) : null}
                    </div>
                    {part.content_url ? (
                      <div className="h-[520px] bg-black/5">
                        <iframe src={toGoogleEmbedUrl(part.content_url)} title={part.title} className="h-full w-full" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen />
                      </div>
                    ) : null}
                    {part.reading_text_body ? (
                      <div className="max-h-[420px] overflow-y-auto whitespace-pre-wrap px-7 pb-6 text-sm leading-6 text-foreground">{part.reading_text_body}</div>
                    ) : null}
                    {part.quiz ? (
                      <div>
                        <div className="flex flex-wrap items-center gap-3 px-7 py-3">
                          <p className="label-caps">Quiz result{focusedName ? ` — ${focusedName}` : ""}</p>
                          {part.quiz.maximum_score != null ? <span className="text-xs text-muted-foreground">Max score {part.quiz.maximum_score}</span> : null}
                          {part.quiz.passing_score != null ? <span className="text-xs text-muted-foreground">Pass mark {part.quiz.passing_score}</span> : null}
                        </div>
                        <QuizResultBlock aptemId={focusedAptemId} learnerName={focusedName} component={part.activity_id} />
                      </div>
                    ) : null}
                  </div>
                ))
              ) : (
                <>
                  {activity.content_url ? (
                    <div className="border-t border-border">
                      <div className="flex items-center justify-between px-7 py-3">
                        <p className="label-caps">{isMedia ? "Activity media" : "Activity content"}</p>
                        <a href={activity.content_url} target="_blank" rel="noreferrer" className="text-xs font-medium text-primary hover:underline">Open in new tab ↗</a>
                      </div>
                      <div className="h-[520px] bg-black/5">
                        <iframe src={toGoogleEmbedUrl(activity.content_url)} title={activity.title} className="h-full w-full" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen />
                      </div>
                    </div>
                  ) : null}

                  {activity.reading_text_body ? (
                    <div className="border-t border-border">
                      <p className="label-caps px-7 py-3">Reading body</p>
                      <div className="max-h-[420px] overflow-y-auto whitespace-pre-wrap px-7 pb-6 text-sm leading-6 text-foreground">{activity.reading_text_body}</div>
                    </div>
                  ) : null}
                </>
              )}

              {activity.quiz && !(activity.parts && activity.parts.length > 1) ? (
                <div className="border-t border-border">
                  <div className="flex flex-wrap items-center gap-3 px-7 py-3">
                    <p className="label-caps">Quiz result{focusedName ? ` — ${focusedName}` : ""}</p>
                    {activity.quiz.maximum_score != null ? <span className="text-xs text-muted-foreground">Max score {activity.quiz.maximum_score}</span> : null}
                    {activity.quiz.passing_score != null ? <span className="text-xs text-muted-foreground">Pass mark {activity.quiz.passing_score}</span> : null}
                  </div>
                  <QuizResultBlock aptemId={focusedAptemId} learnerName={focusedName} component={activity.activity_id ?? ""} />
                </div>
              ) : null}
            </section>

            <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
              <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-7 py-5">
                <div>
                  <h2 className="text-lg font-semibold text-[#182d48]">{isAttendanceLedger ? "Learners who attended" : "Completed learners"}</h2>
                  <p className="mt-1 text-sm text-muted-foreground">
                    {isAttendanceLedger
                      ? "Everyone who attended this session at the source"
                      : "Everyone who completed this same activity at the source"}
                  </p>
                </div>
                <span className="rounded-full bg-success/10 px-3 py-1.5 font-mono text-xs font-medium text-success">{completedList.length} {isAttendanceLedger ? "attended" : "completed"}</span>
              </header>
              <ul className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
                {completedList.map((participant, index) => (
                  <li key={`${participant.aptem_id ?? "x"}-${index}`} className="flex items-center gap-2 border-b border-border px-7 py-2.5">
                    <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-success" />
                    {participant.aptem_id != null ? (
                      <Link
                        to="/journal"
                        search={{ learner: String(participant.aptem_id), period: participant.report_months[0] ?? "" } as never}
                        className="truncate text-sm font-medium text-foreground hover:text-primary hover:underline"
                      >
                        {participant.learner_name}
                      </Link>
                    ) : (
                      <span className="truncate text-sm font-medium text-foreground">{participant.learner_name}</span>
                    )}
                  </li>
                ))}
              </ul>
              {!completedList.length ? (
                <p className="py-10 text-center text-sm text-muted-foreground">
                  {isAttendanceLedger ? "Nobody attended this session at the source yet." : "Nobody has completed this activity at the source yet."}
                </p>
              ) : null}
            </section>
          </>
        ) : null}
      </main>
    </div>
  );
}
